using System;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmApplications:StyledForm { DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,SelectionMode=DataGridViewSelectionMode.FullRowSelect};TextBox search=new TextBox{Width=220};public FrmApplications(){Text="Application Management";Size=new Size(1100,650);var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=60,Padding=new Padding(8)};top.Controls.Add(new Label{Text="Search",AutoSize=true,Margin=new Padding(3,9,3,3)});top.Controls.Add(search);var open=new Button{Text="Open Details",Width=135,Height=36};top.Controls.Add(open);Controls.Add(grid);Controls.Add(top);search.TextChanged+=delegate{LoadData();};open.Click+=delegate{if(grid.CurrentRow==null||grid.CurrentRow.IsNewRow||grid.CurrentRow.Cells["ApplicationId"].Value==null||grid.CurrentRow.Cells["ApplicationId"].Value==DBNull.Value){MessageBox.Show("Select an application first.");return;}new FrmApplicationDetails(Convert.ToInt32(grid.CurrentRow.Cells["ApplicationId"].Value)).ShowDialog(this);LoadData();};LoadData();}void LoadData(){grid.DataSource=new ApplicationQuery().All(search.Text.Trim());if(grid.Columns.Contains("ApplicationId"))grid.Columns["ApplicationId"].Visible=false;} } }
